#include <stdio.h>
#include <stdlib.h>

#define INF (1LL << 62)

static long long P[10005];
static long long dpA[10005], dpB[10005];
static long long A[10005];

static int cmpLL(const void *x, const void *y) {
    long long a = *(const long long *)x;
    long long b = *(const long long *)y;
    return (a > b) - (a < b);
}

int main(void) {
    int N, K, C;
    if (scanf("%d %d %d", &N, &K, &C) != 3) return 0;
    for (int i = 1; i <= N; i++) scanf("%lld", &A[i]);

    /* soma de prefixo */
    P[0] = 0;
    for (int i = 1; i <= N; i++) P[i] = P[i-1] + A[i];

    long long cover;
    if (C == 1) {
        /* etiquetas de comprimento 1: basta escolher os K menores valores */
        qsort(A + 1, (size_t)N, sizeof(long long), cmpLL);
        cover = 0;
        for (int i = 1; i <= K; i++) cover += A[i];
    } else {
        /*
         * DP por camadas (numero de etiquetas usadas):
         * dp[j][i] = menor soma coberta usando exatamente j etiquetas
         *            dentro dos primeiros i quadrados
         * dp[j][i] = min(dp[j][i-1],                      : quadrado i descoberto
         *                dp[j-1][i-C] + soma(i-C+1..i))   : etiqueta termina em i
         * camada 0: dp[0][i] = 0 para todo i
         * Como j <= K e K*C <= N, toda camada j <= K e viavel em i = N.
         * Complexidade: O(N*K) <= O(N^2/C), memoria O(N).
         */
        long long *prev = dpA, *cur = dpB;
        for (int i = 0; i <= N; i++) prev[i] = 0; /* camada j = 0 */
        for (int j = 1; j <= K; j++) {
            cur[0] = INF;
            for (int i = 1; i < C && i <= N; i++) cur[i] = INF;
            for (int i = C; i <= N; i++) {
                long long best = cur[i-1];
                long long t = prev[i-C];
                if (t != INF) {
                    long long cand = t + P[i] - P[i-C];
                    if (cand < best) best = cand;
                }
                cur[i] = best;
            }
            { long long *tmp = prev; prev = cur; cur = tmp; }
        }
        cover = prev[N];
    }

    printf("%lld\n", P[N] - cover);
    return 0;
}
